import csv
from collections import defaultdict
from datetime import datetime

targets = {
 'baef86cb-2941-5d61-87b0-ffa91d79f23a':'actual',
 '1213f3a8-c23d-55b5-8187-4712d49a82ae':'cmd',
 'c5120bcb-e5c2-5714-a171-cbdb1f8ef5ab':'sched',
}
data=defaultdict(list)
with open(VALUES_CSV) as f:
    for r in csv.DictReader(f):
        if r['timeseries_id'] in targets:
            data[targets[r['timeseries_id']]].append((r['timestamp'], float(r['value'])))
for k in data: data[k].sort()

def occupied(ts):
    dt=datetime.fromisoformat(ts)
    return dt.weekday()<5 and 8<=dt.hour<18

def period(ts):
    dt=datetime.fromisoformat(ts)
    return 'before' if (dt.year==2018 and (dt.month<6 or (dt.month==6 and dt.day<=15))) else 'after'

def avg(key, period_label, occ=True):
    vals=[v for ts,v in data[key] if (period(ts)==period_label) and (not occ or occupied(ts))]
    return sum(vals)/len(vals), len(vals)

for lbl in ['before','after']:
    act=avg('actual',lbl)
    cmd=avg('cmd',lbl)
    sch=avg('sched',lbl)
    print(f'{lbl}: actual={act[0]:.3f} (n={act[1]}) cmd={cmd[0]:.3f} sched={sch[0]:.3f}')

